    agregar("G43-L1-01", CLASE_43, "L1", "Cuando doblo cerrado hacia la derecha con el acelerador pisado suena un trac trac trac rápido.", "COTIDIANO", "giro_cerrado_derecha", "trac_trac_trac_al_girar_derecha", "", "", "SI", "NO", "", "L1 trac-trac al girar a la derecha.")
    agregar("G43-L1-02", CLASE_43, "L1", "Hola, al doblar en las esquinas acelerando se escucha un chasquido continuo en la rueda delantera.", "WHATSAPP", "doblar_esquinas_acelerando", "chasquido_continuo_doblar_esquinas", "", "", "SI", "NO", "", "L1 chasquido al doblar en esquinas.")
    agregar("G43-L1-03", CLASE_43, "L1", "Siento una vibración fuerte en la trompa del auto cuando acelero en subida.", "COTIDIANO", "aceleracion_subida", "vibracion_trompa_al_acelerar_subida", "", "", "SI", "NO", "", "L1 vibración bajo aceleración.")
    agregar("G43-L1-04", CLASE_43, "L1", "Hace un sonido de matraca metálica cada vez que giro el timón para estacionar.", "COTIDIANO", "maniobra_estacionar", "matraca_metalica_al_girar_timon", "", "", "SI", "NO", "", "L1 matraca al girar timón.")
    agregar("G43-L1-05", CLASE_43, "L1", "El carro tironea y vibra de lado a lado cuando piso el acelerador en carretera.", "TALLER", "aceleracion_carretera", "tironea_vibra_lado_a_lado_acelerar", "", "", "SI", "NO", "", "L1 tironeo y vibración transversal al acelerar.")
    agregar("G43-L1-06", CLASE_43, "L1", "Buenas, vi grasa negra botada en la parte de adentro del aro de la llanta delantera.", "WHATSAPP", "inspeccion_aro", "grasa_negra_botada_aro_delantero", "", "", "SI", "NO", "", "L1 grasa expulsada en aro.")
    agregar("G43-L1-07", CLASE_43, "L1", "Se siente un clac al arrancar en primera y al cambiar a segunda marcha.", "COTIDIANO", "arranque_primera_segunda", "clac_al_arrancar_y_cambiar", "", "", "SI", "NO", "", "L1 clac al traccionar en cambios bajos.")
    agregar("G43-L1-08", CLASE_43, "L1", "Ayuda ase un click click click bien feo cuando doy la buelta en u.", "ERROR_ORTOGRAFICO", "vuelta_en_u", "click_click_click_vuelta_en_u", "", "", "SI", "NO", "", "L1 click en vuelta en U con ortografía informal.")
    agregar("G43-L1-09", CLASE_43, "L1", "La parte delantera tiembla únicamente cuando mantengo el pie en el acelerador.", "COTIDIANO", "pie_en_acelerador", "trompa_tiembla_solo_al_acelerar", "", "", "SI", "NO", "", "L1 temblor delantero bajo carga de pedal.")
    agregar("G43-L1-10", CLASE_43, "L1", "Suena un traqueteo en la rueda izquierda cuando salgo doblando de un semáforo.", "COTIDIANO", "salida_doblando_semaforo", "traqueteo_rueda_izquierda_doblar", "", "", "SI", "NO", "", "L1 traqueteo al salir doblando.")

    # --- L2 (15 casos) ---
    agregar("G43-L2-01", CLASE_43, "L2", "Sonido de matraca metálica de 5 a 6 clics por segundo al girar cerrado a la izquierda en 2da marcha acelerando; con volante recto en recta no suena nada.", "COTIDIANO", "giro_cerrado_izquierda_acelerando", "matraca_5_a_6_clics_giro_izq_acelerando", "ruido_en_recta_volante_centrado", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L2 clic en giro bajo aceleración descarta zumbido de rodamiento.")
    agregar("G43-L2-02", CLASE_43, "L2", "Fuelle de goma de la homocinética exterior derecha rajado con pérdida total de grasa negra grafitada; las bolas de acero trabajan en seco con chasquido al girar.", "TALLER", "inspeccion_fuelle_roto", "fuelle_homocinetica_rajado|grasa_grafitada_perdida|chasquido_al_girar", "falla_frenos", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L2 guardapolvo roto de homocinética con chasquido al torcer.")
    agregar("G43-L2-03", CLASE_43, "L2", "Vibración transversal severa en la carrocería entre 70 y 90 km/h al pisar a fondo el acelerador; al soltar el pedal y rodar en neutro la vibración desaparece instantáneamente.", "TECNICO", "aceleracion_70_90kmh_vs_neutro", "vibracion_transversal_al_acelerar_70_90kmh", "vibracion_en_neutro_inercia", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L2 junta trípode vibra solo en aceleración y desaparece en neutro descartando llantas.")
    agregar("G43-L2-04", CLASE_43, "L2", "Chasquido clac-clac-clac rítmico en rueda delantera derecha al hacer giros en U hacia la izquierda; no produce zumbidos continuos en autopista recta.", "COTIDIANO", "giro_u_izquierda", "clac_clac_clac_en_giro_u", "zumbido_continuo_autopista", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L2 clac-clac en giro en U descarta rodamiento de maza.")
    agregar("G43-L2-05", CLASE_43, "L2", "Junta trípode interior izquierda con pistas del tulipán marcadas con escalones de desgaste; el semieje tiene holgura rotacional excesiva y vibra en subidas.", "TALLER", "inspeccion_tulipan_subida", "tulipan_con_escalones_desgaste|holgura_rotacional_semieje|vibracion_subidas", "falla_caja_cambios", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L2 tulipán interior desgastado produce vibración bajo carga.")
    agregar("G43-L2-06", CLASE_43, "L2", "Hola maestro, cuando salgo doblando en las esquinas acelerando suena un trac trac trac; si doblo despacito con el embrague pisado sin acelerar no suena casi nada.", "WHATSAPP", "doblar_acelerando_vs_sin_traccion", "trac_trac_al_doblar_con_gas", "silencio_al_doblar_sin_traccion", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L2 homocinética exterior suena con par motor y calla sin tracción.")
    agregar("G43-L2-07", CLASE_43, "L2", "Palier delantero derecho con juego axial y radial perceptible al sacudirlo con la mano en elevador; al acelerar en recta la dirección cabecea lateralmente.", "TALLER", "prueba_manual_elevador_palier", "juego_axial_radial_palier_manual|direccion_cabecea_acelerando", "falla_cremallera", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L2 palier con holgura manual cabecea dirección al acelerar.")
    agregar("G43-L2-08", CLASE_43, "L2", "Crujido metálico repetitivo al dar marcha atrás con la dirección doblada a tope; en marcha adelante en línea recta el vehículo avanza en silencio.", "COTIDIANO", "reversa_tope_direccion", "crujido_repetitivo_reversa_tope_giro", "silencio_recta_marcha_adelante", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 crujido en reversa a tope de dirección descarta embrague.")
    agregar("G43-L2-09", CLASE_43, "L2", "Campana y trípode del semieje con holgura en el estriado de acople a la maza de rueda; produce un chasquido metálico seco al invertir la marcha entre 1ra y reversa.", "TECNICO", "inversion_marcha_1ra_reversa", "chasquido_seco_invertir_marcha|holgura_estriado_semieje_maza", "falla_diferencial", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L2 holgura en estriado de semieje chasquea al invertir marcha.")
    agregar("G43-L2-10", CLASE_43, "L2", "Semieje largo con apoyo intermedio cuyo rodamiento de soporte está zumbando y la junta homocinética exterior tiene la jaula de bolas fisurada.", "TECNICO", "semieje_largo_soporte_intermedio", "jaula_bolas_fisurada_exterior|rodamiento_soporte_intermedio_zumba", "falla_caja_manual", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L2 semieje partido con jaula fisurada y rodaje de apoyo.")
    agregar("G43-L2-11", CLASE_43, "L2", "Buenas, al entrar a rotondas acelerando la rueda derecha hace clac clac clac continuo; no vibra al frenar desde 100 km/h.", "WHATSAPP", "rotonda_acelerando_derecha", "clac_clac_clac_rotonda_acelerando", "vibracion_al_frenar_100kmh", "", "NO", "SI", "Discos de freno alabeados o desgastados", "L2 clac en rotonda sin vibración al frenar descarta discos alabeados.")
    agregar("G43-L2-12", CLASE_43, "L2", "Abrazadera metálica del guardapolvo de palier suelta; entró arena y agua de lluvia lavando la grasa y rayando la pista esférica de la copa homocinética.", "TALLER", "guardapolvo_abrazadera_suelta", "abrazadera_suelta_ingreso_arena|grasa_lavada_pista_rayada", "falla_amortiguador", "", "NO", "NO", "", "L2 ingreso de arena por abrazadera suelta raya homocinética.")
    agregar("G43-L2-13", CLASE_43, "L2", "Tironeo violento en aceleraciones fuertes entre 50 y 80 km/h en 3ra marcha; se comprobaron llantas perfectamente balanceadas a cero gramos.", "COTIDIANO", "aceleracion_50_80kmh_3ra", "tironeo_violento_al_acelerar_3ra", "llantas_balanceadas_cero_gramos", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L2 tironeo en aceleración con llantas balanceadas a cero confirma palier/trípode.")
    agregar("G43-L2-14", CLASE_43, "L2", "Rotura parcial de la jaula porta-esferas de la junta fija exterior; las bolas se montan una sobre otra provocando trabamiento momentáneo de la rueda en giros.", "TECNICO", "giro_trabamiento_rueda", "jaula_portaesferas_rota|bolas_se_montan|trabamiento_en_giro", "falla_freno_mordaza", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L2 jaula rota de homocinética monta bolas y traba rueda en giro.")
    agregar("G43-L2-15", CLASE_43, "L2", "Al doblar en esquina a la derecha suena un clac clac rítmico proporcional a la velocidad de giro de la rueda; al enderezar el timón se silencia.", "COTIDIANO", "esquina_derecha_ritmico", "clac_clac_ritmico_giro_derecha|se_silencia_al_enderezar", "falla_cremallera", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L2 clac proporcional a giro que silencia en recta descarta cremallera.")

    # --- L3 (15 casos) ---
    agregar("G43-L3-01", CLASE_43, "L3", "Inspección técnica de semieje delantero derecho en vehículo de tracción delantera: guardapolvo exterior de termoplástico desgarrado con fuga radial de grasa de bisulfuro de molibdeno salpicada en la cara interior de la llanta. En prueba dinámica en circuito cerrado realizando virajes en círculo cerrado a la izquierda con radio de 5.5 metros a 15 km/h bajo par motor de 120 Nm se registra un golpeteo metálico rítmico de 84 dBA a frecuencia de 4.8 Hz (frecuencia de paso de las 6 bolas sobre la pista ranurada). Con la dirección en línea recta y rodando a la misma velocidad el nivel sonoro decae a 46 dBA descartando rodamiento de maza.", "TECNICO", "viraje_circulo_5_5m_par_120nm", "fuelle_desgarrado_grasa_moly|chasquido_84dba_a_4_8hz_giro|decae_a_46dba_en_recta", "falla_rodaje_maza", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L3 viraje en círculo 15 km/h a 120 Nm acusa 84 dBA a 4.8 Hz confirmando homocinética exterior.")
    agregar("G43-L3-02", CLASE_43, "L3", "Diagnóstico de sacudida transversal de carrocería en aceleración: en recta lisa a 80 km/h al presionar el acelerador al 100% de carga el vehículo experimenta una oscilación lateral de 2.4 mm en la trompa a frecuencia de 18 Hz; en el instante exacto en que se suelta el acelerador o se engrana punto muerto a la misma velocidad de 80 km/h la oscilación cesa instantáneamente (0.1 mm). Se desmontó el semieje izquierdo constatando que el tulipán de la junta trípode interior presenta 3 surcos de desgaste por fatiga de 1.1 mm de profundidad en las pistas de rodillos.", "TECNICO", "oscilacion_lateral_2_4mm_carga_vs_neutro", "oscilacion_lateral_2_4mm_a_18hz_bajo_carga|cesa_a_0_1mm_al_soltar_gas|surcos_tulipan_1_1mm", "desbalanceo_ruedas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 oscilación lateral de 2.4 mm que cesa en neutro confirma trípode interior vs desbalanceo.")
    agregar("G43-L3-03", CLASE_43, "L3", "Desarme en banco de junta homocinética fija de 6 bolas tipo Rzeppa: la jaula porta-bolas de acero templado presenta fractura transversal limpia en dos de las ventanas de alojamiento. Dos bolas de acero de 19.05 mm muestran aplastamiento superficial y craterización por trabajar desalineadas con holgura angular de 14 grados. Al realizar giros de prueba en banco a 30 grados de deflexión el conjunto se bloquea mecánicamente impidiendo la rotación suave.", "TALLER", "desarme_banco_rzeppa_jaula_fracturada", "jaula_rzeppa_fracturada_dos_ventanas|bolas_con_craterizacion|holgura_angular_14_grados|bloqueo_en_banco", "falla_caja_cambios", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L3 banco confirma fractura de jaula Rzeppa con holgura de 14 grados.")
    agregar("G43-L3-04", CLASE_43, "L3", "Hola maestro, tengo un Honda Civic. Cuando volteo en las esquinas acelerando suena un trac-trac-trac rápido como matraca en la rueda izquierda, pero si paso por la misma curva sin acelerar en neutro no suena nada. En recta a 120 km/h el auto rueda parejito sin vibrar el volante. En la serviteca me dijeron que el fuelle de la homocinética está rajado y botó toda la grasa.", "WHATSAPP", "civic_esquinas_acelerando_vs_neutro", "trac_trac_en_esquina_acelerando|silencio_en_neutro|fuelle_rajado_sin_grasa", "vibracion_120kmh_recta", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 relato WhatsApp de trac-trac en esquina bajo tracción que calla en neutro.")
    agregar("G43-L3-05", CLASE_43, "L3", "Análisis con acelerómetros de vibración en semieje delantero derecho: bajo aceleración de par máximo en 3ra marcha (240 Nm a 2200 rpm) se registra aceleración RMS de 6.8 m/s2 en el soporte del palier intermedio. La junta trípode articulada presenta juego radial de 1.4 mm en los rodillos de agujas del trípode por pérdida de lubricante termorresistente NLGI 1.5, provocando desalineación cinemática del árbol de transmisión.", "TECNICO", "acelerometria_palier_6_8ms2_a_240nm", "aceleracion_6_8ms2_a_240nm|juego_radial_tripode_1_4mm|perdida_grasa_nlgi", "falla_soporte_motor", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L3 acelerómetro registra 6.8 m/s2 bajo 240 Nm por holgura de 1.4 mm en trípode.")
    agregar("G43-L3-06", CLASE_43, "L3", "Verificación de palier en torno con reloj comparador de carátula: el semieje macizo de acero forjado presenta un alabeo residual de 1.85 mm en el centro del eje (tolerancia máxima OEM 0.25 mm) debido a golpe contra piedra en trocha. Al circular a más de 60 km/h el desbalance geométrico induce vibración sinusoidal que varía linealmente con la velocidad de giro de la rueda pero no con las RPM del motor.", "TECNICO", "torno_reloj_comparador_alabeo_1_85mm", "alabeo_palier_1_85mm_vs_0_25mm|vibracion_sinusoidal_con_velocidad_rueda", "falla_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 torno confirma alabeo de palier de 1.85 mm tras impacto.")
    agregar("G43-L3-07", CLASE_43, "L3", "Mi carro ase un trac trac trac muy fuerte cuando doblo a la derecha pa entrar a mi cochera acelerando despacito. Si me meto a la cochera en neutro con el vuelito no suena nada. El mecanico le bajo el palier y la copa taba con las canastillas partidas y llena de tierra por el fuelle roto.", "ERROR_ORTOGRAFICO", "cochera_acelerando_vs_neutro", "trac_trac_al_doblar_acelerando|silencio_en_neutro_con_vuelito|copa_canastillas_partidas_tierra", "falla_caja", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 palier con canastillas partidas en cochera con ortografía informal.")
    agregar("G43-L3-08", CLASE_43, "L3", "Rotura por fatiga de chaveta de seguridad y desprendimiento de retén de estrías de semieje dentro del planetario del diferencial: el palier izquierdo experimenta desplazamiento axial libre de 14 mm provocando que la junta homocinética trabaje en su límite de extensión angular (45 grados) con golpeteo seco y roce metálico contra la maza al comprimir la suspensión en baches pronunciados.", "TECNICO", "desplazamiento_axial_palier_14mm", "desplazamiento_axial_14mm|extension_angular_limite_45grados|roce_contra_maza", "falla_diferencial_interno", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L3 desplazamiento de 14 mm en palier por retén suelto.")
    agregar("G43-L3-09", CLASE_43, "L3", "Termografía infrarroja de semiejes tras 30 minutos de conducción urbana: la copa homocinética exterior delantera izquierda alcanza 112°C con humo tenue de grasa calcinada (temperatura de copa derecha normal 48°C). La junta homocinética sufrió gripado por falta de lubricación tras romperse el guardapolvo, provocando fricción acero contra acero en las pistas de contacto.", "TECNICO", "termografia_homocinetica_112c_vs_48c", "temperatura_copa_112c_vs_48c|grasa_calcinada|gripado_friccion_acero_acero", "falla_mordaza_freno", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L3 termografía acusa 112°C en copa homocinética calcinada.")
    agregar("G43-L3-10", CLASE_43, "L3", "Evaluación de holgura circunferencial en banco de torsión: el semieje delantero derecho registra un juego angular libre de 18.5 grados entre la entrada del tulipán y la maza de rueda (especificación máxima 3.0 grados). Al realizar ensayos de aceleración y desaceleración rápida en 1ra marcha se genera un impacto acústico seco de 88 dBA perceptible en la palanca de cambios.", "TECNICO", "banco_torsion_holgura_angular_18_5grados", "juego_angular_18_5_grados_vs_3_0_grados|impacto_acustico_88dba|aceleracion_desaceleracion", "falla_caja_cambios", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 banco de torsión registra 18.5° de juego angular libre en semieje.")
    agregar("G43-L3-11", CLASE_43, "L3", "Cliente reclama sacudida delantera al incorporarse a autopista en 3ra y 4ta velocidad. Se colocaron cámaras de inspección en los bajos del chasis enfocando ambos semiejes: durante la aceleración a 2800 rpm el palier derecho experimenta flexión y cabeceo elíptico de 8 mm provocado por desgaste asimétrico de los 3 rodillos del trípode interior en su guía de deslizamiento.", "TALLER", "camara_chasis_cabeceo_eliptico_8mm", "cabeceo_eliptico_8mm_palier|desgaste_asimetrico_3_rodillos_tripode|sacudida_autopista", "falla_llantas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 cámara en chasis constata cabeceo de 8 mm en palier bajo aceleración.")
    agregar("G43-L3-12", CLASE_43, "L3", "Sustitución de semieje completo tras fractura por corte del eje estriado de la homocinética exterior: la rotura ocurrió exactamente en el entalle de fijación de la tuerca de maza debido a fatiga por microfisuras originadas por torque excesivo de apriete (420 Nm vs especificado 220 Nm) en un cambio de rodamiento previo.", "TECNICO", "fractura_eje_estriado_sobretorque", "fractura_por_corte_eje_estriado|sobretorque_420nm_vs_220nm|fatiga_microfisuras", "falla_rodamiento", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L3 fractura de punta de palier por sobretorque de 420 Nm.")
    agregar("G43-L3-13", CLASE_43, "L3", "Inspección de guardapolvo interior de palier (lado caja de cambios): abrazadera Oetiker de acero inoxidable rota con desprendimiento del labio del fuelle sobre el retén del diferencial; pérdida de 180 ml de valvulina 75W-90 de la transmisión manual que empapó el palier provocando chasquido y golpeteo bajo carga.", "TALLER", "abrazadera_oetiker_rota_fuga_valvulina", "abrazadera_oetiker_rota|fuga_valvulina_75w90_180ml|chasquido_bajo_carga", "falla_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 abrazadera rota de fuelle interior fuga aceite de caja con chasquido.")
    agregar("G43-L3-14", CLASE_43, "L3", "Prueba de esfuerzo en rampa con 18% de pendiente con dirección girada 35 grados: al aplicar embrague y acelerador para arranque en pendiente la homocinética exterior emite chasquidos metálicos violentos de 94 dBA con salto cinemático en el volante; en rampa recta el arranque se produce sin ningún chasquido.", "TECNICO", "rampa_pendiente_18porciento_giro_35grados", "chasquido_94dba_rampa_con_giro_35grados|salto_cinematico_volante|silencio_en_rampa_recta", "falla_disco_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 rampa al 18% con giro a 35° dispara chasquido de 94 dBA.")
    agregar("G43-L3-15", CLASE_43, "L3", "Metrología de rodillos de agujas en trípode de palier: 12 agujas fracturadas y pulverizadas en el rodillo número 2; las partículas de acero templado destruyeron la superficie tratada térmicamente de la cazoleta provocando juego radial de 2.2 mm y sacudida transversal al transferir torque en marchas 2da y 3ra.", "TECNICO", "metrologia_agujas_tripode_pulverizadas", "12_agujas_pulverizadas_en_rodillo|juego_radial_2_2mm|sacudida_al_transferir_torque", "falla_caja_cambios", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L3 rodillo de trípode con 12 agujas pulverizadas genera sacudida en 2da y 3ra.")

