    # --- L1 (10 casos) ---
    agregar("G44-L1-01", CLASE_44, "L1", "El volante empieza a temblar fuerte cuando voy a más de 80 km/h en la carretera.", "COTIDIANO", "carretera_80kmh", "volante_tiembla_a_mas_de_80kmh", "", "", "SI", "NO", "", "L1 volante tiembla a 80 km/h sin detalles.")
