    agregar("G44-L2-02", CLASE_44, "L2", "En autopista nivelada a 100 km/h al soltar el volante el vehículo deriva 2 metros a la derecha en 5 segundos; el volante queda torcido 10 grados a la izquierda para ir derecho.", "TALLER", "deriva_autopista_100kmh", "deriva_2m_a_derecha_en_5s|volante_descentrado_10_grados", "falla_frenos", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L2 deriva lateral y volante descentrado descarta mordaza trabada.")
    agregar("G44-L2-03", CLASE_44, "L2", "Neumáticos delanteros con desgaste pronunciado en diente de sierra (feathering) en la banda de rodadura por exceso de convergencia; los amortiguadores no tienen fuga.", "TECNICO", "inspeccion_diente_de_sierra", "desgaste_diente_sierra_feathering|convergencia_incorrecta", "fuga_amortiguadores", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L2 desgaste en diente de sierra por mala convergencia descarta amortiguadores.")
    agregar("G44-L2-04", CLASE_44, "L2", "Pérdida de plomo de contrapeso exterior de 35 gramos en aro delantero izquierdo; genera vibración rítmica en el volante que se activa a partir de 90 km/h.", "TALLER", "plomo_contrapeso_perdido_35g", "plomo_perdido_35g|vibracion_ritmica_volante_a_partir_90kmh", "falla_homocinetica", "", "NO", "SI", "Juntas homocineticas o palieres danados", "L2 pérdida de contrapeso de 35g produce vibración a 90 km/h.")
    agregar("G44-L2-05", CLASE_44, "L2", "Hola maestro, vibra el asiento y el piso entre 90 y 110 km/h pero el volante no vibra nada; me dijeron que son las llantas traseras desbalanceadas.", "WHATSAPP", "vibracion_asiento_piso_traseras", "vibracion_asiento_y_piso_90_110kmh", "vibracion_en_el_volante", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L2 desbalanceo trasero vibra asiento/piso sin vibrar volante descarta rodamiento.")
    agregar("G44-L2-06", CLASE_44, "L2", "Ambos neumáticos delanteros tienen el hombro interior liso en los alambres mientras el exterior conserva 5 mm de huella por caída negativa excesiva.", "TECNICO", "desgaste_hombro_interior_camber", "hombro_interior_en_alambres|exterior_5mm_huella|caida_negativa_excesiva", "falla_suspension", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L2 hombro interior liso por exceso de caída negativa.")
    agregar("G44-L2-07", CLASE_44, "L2", "Al circular a 95 km/h con acelerador pisado o en neutro la vibración del timón se mantiene idéntica; si freno suavemente el auto frena parejo sin pulsaciones.", "COTIDIANO", "crucero_95kmh_gas_vs_neutro", "vibracion_identica_gas_y_neutro_95kmh", "pulsaciones_al_frenar", "", "NO", "SI", "Discos de freno alabeados o desgastados", "L2 vibración constante en neutro y sin pulsación al frenar descarta discos.")
    agregar("G44-L2-08", CLASE_44, "L2", "Aro de aleación con deformación y salto radial de 2 mm por impacto contra bache; al balancear la rueda exige 60 gramos de contrapeso.", "TALLER", "aro_deformado_salto_radial_2mm", "aro_deformado_salto_radial_2mm|exige_60g_balanceo", "falla_rodaje", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L2 aro abollado con salto radial de 2 mm exige 60g.")
    agregar("G44-L2-09", CLASE_44, "L2", "Vehículo jala fuertemente hacia la izquierda tras caer en una zanja; en el taller comprobaron que la rueda izquierda tiene 1 grado de divergencia abierta.", "TALLER", "zanja_divergencia_abierta_1grado", "jala_a_izquierda_por_zanja|divergencia_abierta_1_grado", "falla_cremallera", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L2 divergencia abierta de 1° tras zanja jala a la izquierda.")
    agregar("G44-L2-10", CLASE_44, "L2", "Zumbido y rumorosidad de rodadura ondulante en autopista; al pasar la mano por la banda de rodadura del neumático se siente escalonada en los tacos.", "COTIDIANO", "tacto_escalonado_banda", "zumbido_ondulante_rodadura|tacos_escalonados_al_tacto", "falla_rodamiento_maza", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L2 taqueado escalonado en neumáticos zumba en autopista descarta rodamiento.")
    agregar("G44-L2-11", CLASE_44, "L2", "Buenas tardes, cuando viajo a 100 km/h vibra el volante; si acelero a 130 km/h la vibración se apaga por completo, solo lo hace en ese rango.", "WHATSAPP", "rango_100_apaga_130", "vibracion_a_100kmh|apaga_a_130kmh", "vibracion_a_alta_velocidad", "", "NO", "SI", "Juntas homocineticas o palieres danados", "L2 vibración en ventana que apaga a 130 descarta palier.")
    agregar("G44-L2-12", CLASE_44, "L2", "Volante girado 15 grados a la derecha en trayectoria recta; el vehículo no presenta ruidos ni juego en la barra de dirección.", "COTIDIANO", "volante_descentrado_15_grados", "volante_girado_15_grados_en_recta", "ruido_juego_barra_direccion", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L2 volante desfasado 15 grados sin juego en cremallera.")
    agregar("G44-L2-13", CLASE_44, "L2", "Llanta trasera derecha con deformación estructural en la carcasa interna (huevo o chichón lateral); produce bamboleo vertical a baja velocidad.", "TALLER", "chichon_lateral_bamboleo", "chichon_lateral_carcasa_deformada|bamboleo_baja_velocidad", "falla_amortiguador", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L2 chichón en carcasa produce bamboleo rítmico.")
    agregar("G44-L2-14", CLASE_44, "L2", "Tendencia direccional a la derecha que obliga a ejercer fuerza constante de 15 N en el timón para mantener el carril; discos no calientan de forma dispar.", "TECNICO", "fuerza_constante_timon_15n", "fuerza_constante_15n_en_timon|tendencia_direccional_derecha", "temperatura_dispar_discos", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L2 fuerza continua de 15 N por alineación descarta mordaza pegada.")
    agregar("G44-L2-15", CLASE_44, "L2", "Vibración en el volante que comenzó justo después de parchar una llanta y no volver a balancearla; antes del pinchazo andaba perfecto.", "COTIDIANO", "parche_sin_balanceo", "vibracion_tras_parchar_llanta_sin_balanceo", "falla_mecanica_previa", "", "NO", "NO", "", "L2 vibración surgida tras parchado sin contrapesos.")

    # --- L3 (15 casos) ---
    agregar("G44-L3-01", CLASE_44, "L3", "Diagnóstico de vibración en banco de balanceo dinámico computarizado: rueda delantera derecha registra desbalance dinámico de 45 gramos en el plano exterior y 25 gramos en el plano interior a 850 rpm (simulando 100 km/h). Al colocar contrapesos de zinc de 45 g y 25 g el desbalance residual se reduce a 0 gramos. En prueba de pista a 100 km/h la vibración del volante disminuye de una amplitud de aceleración RMS de 3.8 m/s2 a 0.2 m/s2. Se descartan discos alabeados dado que al frenar no existe modulación de presión hidráulica ni pulsación.", "TECNICO", "balanceadora_dinamica_45g_25g", "desbalance_45g_exterior_25g_interior|reduccion_a_cero_gramos|amplitud_cae_3_8_a_0_2ms2", "pulsacion_frenado", "", "NO", "SI", "Discos de freno alabeados o desgastados", "L3 balanceo computarizado 45g/25g elimina vibración de 3.8 m/s2 a 100 km/h.")
    agregar("G44-L3-02", CLASE_44, "L3", "Medición en alineadora computarizada 3D con cámaras CCD y dianas de alta definición: el eje delantero registra divergencia total de -0°54' (especificación OEM +0°06' a +0°14' de convergencia positiva), ángulo de caída (camber) izquierdo en -2°18' vs derecho en -0°30' (desequilibrio de caída de 1°48') y avance (caster) simétrico en +3°45'. En carretera esto provoca que el vehículo derive lateralmente 3.5 metros en 100 metros hacia el lado derecho y presente desgaste acelerado en el hombro interno del neumático izquierdo.", "TECNICO", "alineadora_3d_divergencia_menos_0_54", "divergencia_menos_0_54_grados|desequilibrio_camber_1_48_grados|deriva_3_5m_en_100m|desgaste_hombro_interno", "falla_cremallera", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L3 alineadora 3D constata divergencia de -0°54' y delta camber de 1°48'.")
    agregar("G44-L3-03", CLASE_44, "L3", "Evaluación de excentricidad y fuerza radial con balanceadora Road Force (rodillo de carga de 550 kg): el neumático delantero izquierdo presenta variación de fuerza radial (RFV) de 145 N (límite máximo 75 N) debido a superposición irregular de lonas de poliéster internas. Esto induce una fuerza vertical oscilante a 11.2 Hz a 90 km/h que hace vibrar el volante a pesar de que el balanceo estático de masas marque cero gramos.", "TECNICO", "road_force_rfv_145n", "variacion_fuerza_radial_rfv_145n_vs_75n|vibracion_a_11_2hz_a_90kmh|balanceo_estatico_cero", "falla_palier", "", "NO", "SI", "Juntas homocineticas o palieres danados", "L3 Road Force mide 145 N de RFV por defecto de carcasa vibrando a 90 km/h.")
    agregar("G44-L3-04", CLASE_44, "L3", "Hola maestro, tengo un Toyota Corolla. En pista lisa a 90 km/h el volante tiembla como un celular en vibrador, pero si bajo a 70 o subo a 120 km/h el temblor desaparece casi por completo. Al pisar el freno el carro frena suavecito sin vibrar nada. En la llantería le pusieron la rueda a la máquina y faltaban 35 gramos en un lado y 20 en el otro.", "WHATSAPP", "corolla_90kmh_vs_frenado_suave", "volante_tiembla_a_90kmh|desaparece_a_70_y_120|frena_suave_sin_vibrar|faltaban_35g_y_20g", "vibracion_al_frenar", "", "NO", "SI", "Discos de freno alabeados o desgastados", "L3 relato WhatsApp de desbalanceo a 90 km/h con descarte explícito de frenado.")
    agregar("G44-L3-05", CLASE_44, "L3", "Inspección de desgaste con profundímetro digital de banda de rodamiento: neumático delantero derecho registra 1.8 mm en el hombro interior, 4.2 mm en el centro y 6.1 mm en el hombro exterior (desgaste cónico asimétrico de 4.3 mm); prueba de alineación confirma ángulo de caída negativa de -2°42' debido a deformación del anclaje del amortiguador tras colisión con berma.", "TECNICO", "profundimetro_desgaste_conico_4_3mm", "profundimetro_1_8mm_vs_6_1mm|desgaste_conico_4_3mm|camber_menos_2_42_grados", "falla_buje_trapecio", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L3 profundímetro mide delta de 4.3 mm en hombros por caída de -2°42'.")
    agregar("G44-L3-06", CLASE_44, "L3", "Análisis con goniómetro digital de centrado de volante: con el vehículo circulando en línea recta a 80 km/h en carril plano sin peralte el volante requiere un desfase angular permanente de 14.5 grados a la izquierda para mantener la trayectoria. La alineadora 3D constata que las barras axiales de dirección fueron reguladas asimétricamente (+0°28' en rueda izquierda y -0°32' en rueda derecha).", "TECNICO", "goniometro_volante_desfase_14_5_grados", "desfase_volante_14_5_grados_en_recta|barras_axiales_asimetricas|alineacion_descompensada", "falla_cremallera", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L3 goniómetro mide desfase de 14.5° por regulación asimétrica de axiales.")
    agregar("G44-L3-07", CLASE_44, "L3", "Mi carro ase una vibrasion muy fuerte en el timon cuando voy a noventa en la panamericana. Si suelto el acelerador en neutro sigue vibrando igualito a noventa. Pero cuando freno no tiembla nada de nada. El de la llanteria me mostro que el aro de fierro taba golpeao y le faltaba 40 gramos de plomo.", "ERROR_ORTOGRAFICO", "vibrasion_90_panamericana_neutro", "vibrasion_en_el_timon_a_noventa|sigue_en_neutro|no_tiembla_al_frenar|falta_40g_plomo", "vibracion_frenado", "", "NO", "SI", "Discos de freno alabeados o desgastados", "L3 vibración a 90 km/h que sigue en neutro y no vibra al frenar con ortografía informal.")
    agregar("G44-L3-08", CLASE_44, "L3", "Inspección de runout radial y lateral de rueda completa montada en buje con reloj comparador de carátula: salto radial del neumático de 1.9 mm (especificación máxima 0.8 mm) y alabeo lateral del aro de 1.4 mm. Esto genera vibración de primer armónico a 13.5 Hz a 100 km/h provocando fatiga en la columna de dirección.", "TECNICO", "reloj_comparador_salto_radial_1_9mm", "salto_radial_neumatico_1_9mm|alabeo_aro_1_4mm|primer_armonico_13_5hz_a_100kmh", "falla_rodaje_maza", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L3 reloj comparador mide salto radial de 1.9 mm en neumático.")
    agregar("G44-L3-09", CLASE_44, "L3", "Vehículo presenta arrastre direccional hacia la derecha con ángulo de empuje (thrust angle) del eje trasero desfasado en +0°38' respecto al eje geométrico central. El eje trasero rígido se encuentra desalineado por impacto lateral contra bordillo provocando que el auto circule 'de costado' (dog tracking) con desgaste prematuro en los hombros externos de ambas llantas derechas.", "TECNICO", "angulo_empuje_thrust_angle_0_38", "thrust_angle_trasero_mas_0_38_grados|dog_tracking_de_costado|desgaste_hombros_derechos", "falla_amortiguadores", "", "NO", "SI", "Amortiguadores reventados o bujes de suspension gastados", "L3 thrust angle trasero de +0°38' produce efecto dog tracking y deriva.")
    agregar("G44-L3-10", CLASE_44, "L3", "Sonometría diferencial de rumorosidad de rodadura: el habitáculo registra 74 dBA a 90 km/h con modulación cíclica de 7 Hz debida a desgaste en facetas poligonales (cupping) en los neumáticos traseros provocado por rodar 40,000 km sin rotación. Al rotar las ruedas a llantas de prueba lisas nuevas el nivel sonoro decae a 58 dBA descartando daño en rodamientos de maza.", "TECNICO", "sonometria_cupping_74dba_vs_58dba", "ruido_74dba_modulacion_7hz_cupping|decae_a_58dba_con_llantas_nuevas|rodamientos_ok", "falla_rodamiento_rueda", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L3 cupping en neumáticos genera 74 dBA que cae a 58 dBA con gomas nuevas descartando rodamientos.")
    agregar("G44-L3-11", CLASE_44, "L3", "Desbalanceo dinámico en ruedas traseras: balanceadora acusa 50 gramos de desbalance estático en rueda trasera izquierda. En carretera abierta entre 95 y 115 km/h el volante permanece completamente quieto pero los respaldos de los asientos delanteros oscilan visiblemente con amplitud de 5 mm y el espejo retrovisor interior vibra empañando la visión trasera.", "TALLER", "desbalance_trasero_50g_oscilacion_asientos", "desbalance_trasero_50g|volante_quieto|respaldos_oscilan_5mm|retrovisor_vibra", "falla_palier", "", "NO", "SI", "Juntas homocineticas o palieres danados", "L3 desbalanceo trasero de 50g vibra asientos y espejo manteniendo volante firme.")
    agregar("G44-L3-12", CLASE_44, "L3", "Comprobación de alineación de dirección tras sustitución de terminales: convergencia delantera descalibrada a +1°12' (exceso de convergencia cerrada de 12 mm en regla métrica). El vehículo presenta una dirección hipersensible en curvas y chirrido continuo de neumáticos en giros a baja velocidad (20 km/h) sobre asfalto pulido de estacionamiento.", "TECNICO", "convergencia_cerrada_1_12_grados", "convergencia_cerrada_mas_1_12_grados|exceso_12mm_convergencia|chirrido_a_20kmh_estacionamiento", "falla_cremallera", "", "NO", "SI", "Cremallera de direccion asistida con holgura o fuga", "L3 convergencia cerrada de +1°12' genera chirrido en maniobras.")
    agregar("G44-L3-13", CLASE_44, "L3", "Medición de concentricidad y balanceo de conjunto aro-neumático: neumático montado con rotación de 180 grados desalineada respecto al punto amarillo de mínima masa del neumático con la válvula del aro; la máquina acusa 65 gramos de desbalance; tras desinflar, rotar la cubierta alineando punto amarillo con válvula el desbalance se reduce naturalmente a 15 gramos.", "TALLER", "optimizacion_match_mounting_punto_amarillo", "desalineacion_punto_amarillo_65g|match_mounting_reduce_a_15g|vibracion_eliminada", "falla_disco_freno", "", "NO", "SI", "Discos de freno alabeados o desgastados", "L3 match mounting con punto amarillo reduce desbalance de 65g a 15g.")
    agregar("G44-L3-14", CLASE_44, "L3", "Evaluación de deriva dinámica con dinamómetro de volante: en pista con 0% de pendiente transversal a 100 km/h el vehículo requiere 2.2 Nm de torque corrector continuo hacia la izquierda para contrarrestar ángulo de avance (caster) desparejo (rueda derecha con +2°10' vs izquierda con +3°40', delta de 1°30' por brazo doblado).", "TECNICO", "torque_corrector_2_2nm_delta_caster", "torque_corrector_2_2nm|delta_caster_1_30_grados|deriva_continua_hacia_derecha", "falla_mordaza_freno", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L3 torque corrector de 2.2 Nm por delta de caster de 1°30'.")
    agregar("G44-L3-15", CLASE_44, "L3", "Vibración armónica de alta frecuencia a 105 km/h analizada con acelerómetro FFT en volante: pico de aceleración de 2.8 m/s2 centrado exactamente en 14.1 Hz correspondiente a 1X velocidad de rotación de rueda (105 km/h con neumático 205/55R16 = 14.1 rps); la balanceadora confirmó 35 gramos de desbalance en rueda delantera izquierda.", "TECNICO", "acelerometria_fft_14_1hz_a_105kmh", "pico_fft_14_1hz_a_105kmh_2_8ms2|frecuencia_1x_rotacion_rueda|desbalance_35g", "falla_palier", "", "NO", "SI", "Juntas homocineticas o palieres danados", "L3 acelerometría FFT confirma pico en 14.1 Hz (1X rueda) por 35g de desbalance.")

    return casos
